import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Project context","description":"AGENTS.md, instructions, references, snapshots, and compaction — how PrioriCode learns your project and stays inside the context window.","frontmatter":{"title":"Project context","description":"AGENTS.md, instructions, references, snapshots, and compaction — how PrioriCode learns your project and stays inside the context window."},"headers":[],"relativePath":"using/context.md","filePath":"using/context.md"}'),o={name:"using/context.md"};function n(r,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<p>The model is smart; your repo is specific. PrioriCode&#39;s job is to feed the second into the first, every turn, without drowning it. There are four mechanisms: standing instructions, extra instruction files, referenced projects, and the context-window plumbing itself.</p><h2 id="agents-md-—-the-project-s-own-doc" tabindex="-1">AGENTS.md — the project&#39;s own doc <a class="header-anchor" href="#agents-md-—-the-project-s-own-doc" aria-label="Permalink to &quot;AGENTS.md — the project&#39;s own doc&quot;">​</a></h2><p>The file every agent reads first. Search order, from the session directory <strong>up to the repo root</strong> — the first match wins:</p><ol><li><code>AGENTS.md</code></li><li><code>CLAUDE.md</code></li><li><code>CONTEXT.md</code> <em>(deprecated — prefer AGENTS.md)</em></li></ol><p>Plus a global file: <code>&lt;config dir&gt;/AGENTS.md</code> (<code>~/.config/prioricode/AGENTS.md</code> on Linux) is always in context, and if it&#39;s missing, <code>~/.claude/CLAUDE.md</code> is picked up instead (disable with <code>PRIORICODE_DISABLE_CLAUDE_CODE=1</code>).</p><p>Contents are injected with a header (<code>Instructions from: &lt;path&gt;</code>), so the model knows who wrote it. Treat it as onboarding docs for a very fast, very literal coworker:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># AGENTS.md</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Bun monorepo. </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`bun run dev\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> starts the CLI, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`bun test\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> per package.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never edit </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`packages/sdk/openapi.json\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — it&#39;s generated.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Commits: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`type(scope): summary\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">. Ask before pushing.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The DB schema is in </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`packages/core/src/**/sql.ts\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; migrations via script/migration.ts.</span></span></code></pre></div><p>Good AGENTS.md content: commands that must pass, files that are sacred, conventions the linter can&#39;t catch, &quot;never do X&quot; rules. Bad content: the README, a tutorial, your feelings about tabs. (And yes — the reason this repo&#39;s own AGENTS.md tells you how releases work is exactly this feature at work.)</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Only the file at the match is loaded — there&#39;s no stacking of every ancestor AGENTS.md. If your monorepo has per-package notes, add them with <code>instructions</code> below.</p></div><h2 id="instructions-—-more-files-urls-globs" tabindex="-1">instructions — more files, URLs, globs <a class="header-anchor" href="#instructions-—-more-files-urls-globs" aria-label="Permalink to &quot;instructions — more files, URLs, globs&quot;">​</a></h2><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;instructions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;docs/conventions.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// relative, walked up to worktree</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;packages/*/AGENTS.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// globs work</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;~/company-styleguide.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// absolute + ~ fine</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;https://intranet.example.com/rules.md&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // fetched at session start</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>URLs are fetched with a 5-second timeout and injected like any file.</p><h2 id="references-—-a-second-repo-in-context" tabindex="-1">references — a second repo in context <a class="header-anchor" href="#references-—-a-second-repo-in-context" aria-label="Permalink to &quot;references — a second repo in context&quot;">​</a></h2><p><code>references</code> (config, replacing the deprecated <code>reference</code> key) attaches another directory — local path or git repository — whose files are readable without an <code>external_directory</code> prompt and searchable by name: <code>@frontend</code> mentions pull in the referenced project. Used by this very workspace (the <code>effect</code> reference). It&#39;s aimed at polyglot setups where the truth lives in two trees. See <a href="./../reference/config.html">config reference</a>.</p><h2 id="keeping-the-lights-on-snapshots-truncation-compaction" tabindex="-1">Keeping the lights on: snapshots, truncation, compaction <a class="header-anchor" href="#keeping-the-lights-on-snapshots-truncation-compaction" aria-label="Permalink to &quot;Keeping the lights on: snapshots, truncation, compaction&quot;">​</a></h2><p>The other half of context is <em>not</em> letting it rot:</p><ul><li><strong>File snapshots.</strong> On by default (<code>snapshot: true</code>). PrioriCode tracks workspace changes so <a href="./sessions.html">undo/redo</a> can rewind code and conversation together, and diffs stay honest after the fact.</li><li><strong>Tool output truncation.</strong> Long command output is capped (2,000 lines / 50 KB by default) — but never <em>lost</em>: the full text spills to a file in the tool-output directory, with the path printed. Tweak <code>tool_output.max_lines</code> / <code>max_bytes</code>.</li><li><strong>Compaction.</strong> The <code>compaction</code> block decides what happens when the window fills: automatic summary of old turns (<code>auto</code>, on by default), what stays verbatim (<code>tail_turns</code>, <code>preserve_recent_tokens</code>), a <code>reserved</code> safety buffer, and <code>prune</code> (drop old tool output — off by default). Manual trigger: <code>/compact</code>. Kill switches: <code>PRIORICODE_DISABLE_AUTOCOMPACT</code> / <code>PRIORICODE_DISABLE_PRUNE</code>.</li><li><strong>Images.</strong> Pasted/attached images are auto-resized before sending (<code>attachment.image</code> — max 2000×2000 and a 5 MB base64 cap by default). Turn it off if your model likes pixels rude.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A session that keeps forgetting is a session that got compacted. Check the sidebar&#39;s context meter (<code>used %</code> and spend), and <code>/compact</code> at a natural seam — after a phase, not mid-thought — so the summary falls on the boring part of history.</p></div><h2 id="rules-in-one-table" tabindex="-1">Rules, in one table <a class="header-anchor" href="#rules-in-one-table" aria-label="Permalink to &quot;Rules, in one table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Want</th><th>Use</th></tr></thead><tbody><tr><td>&quot;Always use bun, never npm&quot;</td><td><code>AGENTS.md</code></td></tr><tr><td>Per-package conventions</td><td><code>instructions</code> globs</td></tr><tr><td>Keep secrets out of context</td><td><code>read</code> permission <code>*.env: ask</code> (<a href="./permissions.html">permissions</a>)</td></tr><tr><td>Another repo in view</td><td><code>references</code></td></tr><tr><td>Reusable procedures</td><td><a href="./../extending/skills.html">skills</a></td></tr><tr><td>Project-specific commands</td><td><a href="./../extending/commands.html">custom commands</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../configure/files.html">Config files</a> — Where config and context files are discovered. <ul><li><a href="./../extending/skills.html">Skills</a> — Procedures the agent loads on demand instead of bloating AGENTS.md.</li><li><a href="./sessions.html">Sessions</a> — Compaction, undo, and the context meter.</li><li><a href="./coordination.html">Coordination</a> — Multiple sessions, one repo, no collisions.</li></ul></li></ul>`,22)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
